// Turns keycloak/theme/vinaire (Keycloak's sign-in theme in Vinaire's look, Roadmap Phase 85b) into
// src/lib/keycloakThemeFiles.ts, so the browser can hand the theme out (a zip, a ConfigMap) without a
// server of its own. `--check` fails when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..", "keycloak", "theme", "vinaire");
const files = ["login/theme.properties", "login/resources/css/vinaire.css"];
const out = join(dirname(fileURLToPath(import.meta.url)), "..", "src", "lib", "keycloakThemeFiles.ts");

let ts =
  "// GENERATED by scripts/gen-keycloak-theme.mjs from keycloak/theme/vinaire — do not edit; run `npm run gen:keycloak-theme`.\n" +
  "export const KEYCLOAK_THEME_FILES: { path: string; content: string }[] = [\n";
for (const f of files) {
  const text = readFileSync(join(root, f), "utf8").replace(/\r\n/g, "\n");
  ts += `  { path: ${JSON.stringify(f)}, content: ${JSON.stringify(text)} },\n`;
}
ts += "];\n";

if (process.argv.includes("--check")) {
  let cur = "";
  try {
    cur = readFileSync(out, "utf8").replace(/\r\n/g, "\n");
  } catch {}
  if (cur !== ts) {
    console.error("src/lib/keycloakThemeFiles.ts is out of date: run `npm run gen:keycloak-theme`");
    process.exit(1);
  }
  console.log("keycloak theme ok");
} else {
  writeFileSync(out, ts);
  console.log("wrote", out);
}
